cat <<'EOF' >> app/views/pwa/service_worker.js.erb

self.addEventListener("push", (event) => {
  if (!event.data) return

  const { title, options } = event.data.json()
  event.waitUntil(showNotification(title, options))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()

  const path = event.notification.data?.path || event.notification.data?.url
  if (!path) return

  event.waitUntil(openNotification(path))
})

async function showNotification(title, options) {
  await self.registration.showNotification(title, options)

  const badge = options?.data?.badge
  if (badge && "setAppBadge" in self.navigator) {
    try {
      await self.navigator.setAppBadge(badge)
    } catch {
      // Ignore badge errors on platforms that restrict setAppBadge
    }
  }
}

async function openNotification(path) {
  const targetUrl = new URL(path, self.location.origin)
  const clientList = await self.clients.matchAll({ type: "window", includeUncontrolled: true })

  for (const client of clientList) {
    const clientUrl = new URL(client.url)
    if (clientUrl.origin === targetUrl.origin && clientUrl.pathname === targetUrl.pathname && clientUrl.hash === targetUrl.hash && "focus" in client) {
      return client.focus()
    }
  }

  if (self.clients.openWindow) {
    return self.clients.openWindow(targetUrl.href)
  }
}
EOF

